def has_cycle(g, u, seen, stack):
    seen.add(u); stack.add(u)
    for v in g[u]:
        if v in stack: return True
        if v not in seen and has_cycle(g, v, seen, stack): return True
    stack.remove(u)
    return False
g = {0: [1], 1: [2], 2: []}
print(has_cycle(g, 0, set(), set()))

from collections import deque
g = {0: [1, 2], 1: [2], 2: []}
indeg = {u: 0 for u in g}
for u in g:
    for v in g[u]: indeg[v] += 1
q = deque([u for u in g if indeg[u] == 0]); out = []
while q:
    u = q.popleft(); out.append(u)
    for v in g[u]:
        indeg[v] -= 1
        if indeg[v] == 0: q.append(v)
print(out)

def dfs(u, parent, seen, g):
    seen.add(u)
    for v in g[u]:
        if v not in seen:
            if dfs(v, u, seen, g): return True
        elif v != parent:
            return True
    return False
g = {0: [1, 2], 1: [0, 2], 2: [0, 1]}
print(dfs(0, -1, set(), g))

edges = [(1,'A','B'), (2,'B','C'), (10,'A','C'), (3,'C','D')]
parent = {x: x for x in 'ABCD'}
def find(x):
    while parent[x] != x: x = parent[x]
    return x
total = 0; used = 0
for w, a, b in sorted(edges):
    ra, rb = find(a), find(b)
    if ra != rb: parent[ra] = rb; total += w; used += 1
print(total, used)

