import heapq
g = {0: [(1, 4), (2, 1)], 1: [(3, 1)], 2: [(1, 2), (3, 5)], 3: []}
dist = {0: 0}
h = [(0, 0)]
while h:
    d, u = heapq.heappop(h)
    if d > dist.get(u, float('inf')): continue
    for v, w in g[u]:
        nd = d + w
        if nd < dist.get(v, float('inf')):
            dist[v] = nd; heapq.heappush(h, (nd, v))
print(dist[1], dist[3])

def dfs(u, colour, g):
    colour[u] = 1
    for v in g[u]:
        if colour[v] == 1: return True
        if colour[v] == 0 and dfs(v, colour, g): return True
    colour[u] = 2
    return False
